import type { Metadata } from "next";
import { db } from "@/lib/db";
import { UseCaseLanding, type UseCaseContent } from "@/components/marketing/UseCaseLanding";

export const dynamic = "force-dynamic";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Singapore VPS Hosting — Low-Latency VPS for Asia-Pacific",
  description:
    "Singapore VPS hosting for low latency across Asia-Pacific — SEA, India, Australia, and East Asia. Full-root NVMe servers with dedicated IP and DDoS, from $6.49/mo.",
  alternates: { canonical: "/singapore-vps-hosting" },
  openGraph: {
    type: "article",
    title: "Singapore VPS Hosting — Low-Latency VPS for Asia-Pacific",
    description:
      "A Singapore-based NVMe VPS built for Asia-Pacific latency: SEA, India, Australia, and East Asia. Full root, dedicated IP, DDoS, from $6.49/mo.",
    url: `${APP_URL}/singapore-vps-hosting`,
  },
};

const content: UseCaseContent = {
  eyebrow: "Singapore VPS hosting",
  title: "A Singapore VPS built for",
  highlight: "Asia-Pacific",
  sub: "Serve users across Southeast Asia, India, Australia, and East Asia from a Singapore datacenter — full-root NVMe servers with a dedicated IP and DDoS, from $6.49/mo.",
  intro: [
    "If your users are in Asia-Pacific, geography is performance. A request from Jakarta, Manila, Sydney, or Mumbai that has to cross the Pacific to a US datacenter and back pays for it in every page load, API call, and game tick. Hosting close to your audience is the single biggest latency win you can buy.",
    "Nxeon runs a datacenter in Singapore — one of the best-connected network hubs in the region, sitting on the submarine cable routes that link Southeast Asia, South Asia, Oceania, and East Asia. From there, round-trips to major APAC population centres stay low, which is exactly what interactive apps, real-time services, and game servers need.",
    "It's the same full-root NVMe platform everywhere else: enterprise NVMe on a self-healing ZFS mirror, a dedicated IPv4, always-on DDoS protection, daily backups, and one-click deploys in about 47 seconds — now sitting where your Asia-Pacific traffic actually is.",
  ],
  whyTitle: "Why Singapore for APAC",
  why: [
    { title: "Low latency across the region", body: "A Singapore location keeps round-trips short to Southeast Asia, India, Australia, and East Asia — no trans-Pacific detour for every request." },
    { title: "A premier network hub", body: "Singapore is a major interconnection point on the region's submarine cable routes, so peering and reachability across APAC are excellent." },
    { title: "Enterprise NVMe on ZFS", body: "Fast, consistent storage on enterprise NVMe over a self-healing ZFS mirror — low network latency paired with low disk latency." },
    { title: "Dedicated IPv4 + DDoS included", body: "Your own IPv4 and always-on DDoS protection with a managed firewall come with every plan — no add-on fees, region included." },
    { title: "Built for real-time workloads", body: "Interactive apps, APIs, and game servers live or die on latency. Hosting near your APAC players and users is the difference makers can feel." },
    { title: "Full root, fast deploys", body: "SSH in and run anything, with one-click OS and app images and a median deploy around 47 seconds. Backups and snapshots included." },
  ],
  steps: [
    { title: "Sign up free", body: "Create your account with no credit card required and open the deploy wizard." },
    { title: "Deploy in Singapore", body: "Choose a one-click OS or app image and deploy to the Singapore datacenter — live in about 47 seconds with a dedicated IP." },
    { title: "Point your domain", body: "Aim your DNS at the server's IP and issue SSL. Your Asia-Pacific users now hit a nearby server, not one across an ocean." },
    { title: "Tune and scale", body: "With full root you control the stack; one-click resize adds vCPU, RAM, or disk without a rebuild as your APAC traffic grows." },
  ],
  specNote:
    "For a Singapore-hosted site or API serving APAC, Starter (2 GB) or Standard (4 GB) is a strong start; step up to Pro (8 GB) for busier apps or game servers. All plans deploy in Singapore with a dedicated IP — resize any time.",
  faq: [
    { q: "Where exactly are the servers located?", a: "Nxeon runs a datacenter in Singapore. It's a single, well-connected APAC location — we don't claim regions we don't operate, so what you see is a genuine Singapore-based VPS." },
    { q: "Who benefits most from a Singapore VPS?", a: "Anyone serving Asia-Pacific users: sites and apps for Southeast Asia (Singapore, Malaysia, Indonesia, the Philippines, Thailand, Vietnam), India, Australia, and East Asia. Hosting near your audience cuts latency on every request." },
    { q: "Will latency be good to Australia and India too?", a: "Singapore is a central APAC network hub on major submarine cable routes, so round-trips to Oceania and South Asia are strong — typically far better than routing those users to a US or EU datacenter." },
    { q: "Do Singapore plans include the same features?", a: "Yes. Every plan includes enterprise NVMe on a self-healing ZFS mirror, a dedicated IPv4, always-on DDoS protection, a managed firewall, daily backups, snapshots, IPv6, and a 99.9% uptime SLA — from $6.49/mo." },
    { q: "Can I host a game server in Singapore?", a: "Yes. Low regional latency plus full root and dedicated NVMe compute make it well suited to game servers and other real-time workloads for APAC players. Pick a plan by player count and resize any time without a rebuild." },
  ],
  related: [
    { label: "VPS hosting", href: "/vps" },
    { label: "Cheap VPS", href: "/cheap-vps-hosting" },
    { label: "Best value VPS", href: "/best-value-vps" },
    { label: "Pricing", href: "/pricing" },
    { label: "Free tools", href: "/tools" },
  ],
};

export default async function SingaporeVpsHostingPage() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  return <UseCaseLanding content={content} plans={plans} />;
}

