export type PlanCard = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

function planFeatures(p: PlanCard): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  return [
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    `${p.bandwidthTB} TB bandwidth`,
    "Full root access",
    "Free DDoS protection",
  ];
}

export function PricingGrid({ plans, annualPct = 0 }: { plans: PlanCard[]; annualPct?: number }) {
  // Prices are USD-cents in the DB; `money` converts them to the visitor's display
  // currency (geo/manual) for rendering only — checkout still charges the USD amount.
  const money = useDisplayMoney();
  // Billing toggle — Annual is on by default when it's a real discount, so the
  // headline price shows the better-value figure first. Switching to Monthly shows
  // the undiscounted monthly price. Every figure is DB-fed through termPriceCents,
  // the SAME formula checkout charges — displayed === charged.
  const annualAvailable = annualPct > 0;
  const [annual, setAnnual] = useState(true);
  const showAnnual = annual && annualAvailable;

  // Highlight the middle plan (by position) as "Most popular"; the top (most
  // expensive) plan gets a "Best value / most resources" anchor so the mid tier
  // reads as the smart buy.
  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
  const topIdx = plans.length >= 3 ? plans.length - 1 : -1;
  const fromCents = plans.length ? Math.min(...plans.map((p) => p.priceCents)) : 0;
  const topCents = plans.length ? Math.max(...plans.map((p) => p.priceCents)) : 0;

  if (plans.length === 0) {
    return (
      <div className="card text-center text-slate-400">
        Plans are being provisioned. Please check back shortly.
      </div>
    );
  }

  // No promo banner here: first-month-free is a Shared Web Hosting offer only
  // (see lib/promo-redemption.ts firstMonthFreeAppliesTo). VPS bills the regular
  // price from month one — the price shown IS what checkout charges.

  return (
    <div>
      {annualAvailable && (
        <div className="mb-8 flex flex-col items-center gap-2">
          <div className="inline-flex items-center rounded-full border border-white/10 bg-navy-900/70 p-1 backdrop-blur">
            <button
              type="button"
              aria-pressed={!annual}
              onClick={() => setAnnual(false)}
              className={`rounded-full px-5 py-1.5 text-sm font-semibold transition-colors ${
                !annual ? "bg-white/10 text-white" : "text-slate-400 hover:text-white"
              }`}
            >
              Monthly
            </button>
            <button
              type="button"
              aria-pressed={annual}
              onClick={() => setAnnual(true)}
              className={`flex items-center gap-2 rounded-full px-5 py-1.5 text-sm font-semibold transition-colors ${
                annual ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow" : "text-slate-400 hover:text-white"
              }`}
            >
              Annual
              <span className={`rounded-full px-1.5 py-0.5 text-[10px] font-bold ${annual ? "bg-white/20 text-white" : "bg-emerald-500/15 text-emerald-300"}`}>
                –{annualPct}%
              </span>
            </button>
          </div>
          <p className="text-xs text-slate-500">
            {showAnnual ? "Billed yearly · cancel anytime" : "Billed monthly · switch to annual to save"}
          </p>
        </div>
      )}
      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
        {plans.map((p, i) => {
          const popular = i === popularIdx;
          const topTier = i === topIdx;
          const regular = p.priceCents;
          // Effective $/mo on the annual term — DB-fed via the shared term formula,
          // the same one checkout charges. Only shown when annual is a real discount.
          const annualPerMo = annualAvailable ? Math.round(termPriceCents(regular, ANNUAL_TERM_MONTHS, annualPct) / ANNUAL_TERM_MONTHS) : 0;
          const annualTotal = annualAvailable ? termPriceCents(regular, ANNUAL_TERM_MONTHS, annualPct) : 0;
          const bigCents = showAnnual ? annualPerMo : regular;
          return (
          <div
            key={p.id}
            className={`group relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-300 hover:-translate-y-1.5 ${
              popular
                ? "border-brand-500/40 bg-navy-850/80 glow-brand"
                : "border-white/[0.06] bg-navy-900/70 hover:border-brand-500/30 hover:bg-navy-850/70 hover:shadow-[0_0_40px_-10px_rgb(111_71_245_/_0.4)]"
            }`}
          >
            {popular && (
              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white shadow-lg">
                Most popular
              </span>
            )}
            {topTier && !popular && (
              <span className="absolute -top-3 right-4 rounded-full border border-white/10 bg-navy-950 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-slate-300 shadow-lg">
                Best value
              </span>
            )}
            <div className="flex items-center justify-between">
              <h3 className="text-base font-semibold text-white">{p.name}</h3>
              <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-300">
                {topTier ? "Most resources" : planAudience(p)}
              </span>
            </div>
            <div className="mt-3">
              <div className="flex items-end gap-1">
                <span className="text-4xl font-bold tracking-tight">{money(bigCents)}</span>
                <span className="mb-1 text-sm text-slate-400">/mo</span>
              </div>
              {showAnnual ? (
                <p className="mt-1 text-[11px] leading-snug text-emerald-300">
                  {money(annualTotal)} billed yearly — save {annualPct}% vs {money(regular)}/mo
                </p>
              ) : annualAvailable ? (
                <p className="mt-1 text-[11px] leading-snug text-slate-500">
                  or {money(annualPerMo)}/mo billed annually — save {annualPct}%
                </p>
              ) : (
                <p className="mt-1 text-[11px] leading-snug text-slate-500">
                  Billed monthly. Cancel anytime.
                </p>
              )}
            </div>
            <div className="mt-4 flex items-start gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <span className="mt-0.5 text-brand-300" aria-hidden>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M9 18h6M10 21h4M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.1h6c0-.8.4-1.6 1-2.1A7 7 0 0 0 12 2z" />
                </svg>
              </span>
              <p className="text-[12px] leading-snug text-slate-300">
                <span className="font-semibold text-slate-200">Great for: </span>
                {planTip(p)}
              </p>
            </div>
            <ul className="mt-5 flex-1 space-y-3 text-sm">
              {planFeatures(p).map((f) => (
                <li key={f} className="flex items-center gap-2.5 text-slate-300">
                  <span className="flex h-4.5 w-4.5 shrink-0 items-center justify-center rounded-full bg-brand-500/15 text-brand-300">
                    <IconCheck size={12} />
                  </span>
                  {f}
                </li>
              ))}
            </ul>
            <Link
              href="/register"
              className={`mt-7 w-full ${popular ? "btn-deploy" : "btn-secondary"}`}
            >
              Deploy now
            </Link>
          </div>
          );
        })}
      </div>
      <p className="mt-6 text-center text-sm text-slate-500">
        From <span className="font-semibold text-slate-300">{money(fromCents)}</span> to{" "}
        <span className="font-semibold text-slate-300">{money(topCents)}/mo</span> — every tier gets the same platform, root access and protection; you only choose the horsepower.
        {annualPct > 0 && (
          <>
            {" "}Prefer to pay yearly?{" "}
            <span className="font-semibold text-emerald-300">Annual billing saves {annualPct}%</span> — choose your term in the deploy wizard.
          </>
        )}
      </p>
    </div>
  );
}

model Plan {
  id           String        @id @default(cuid())
  slug         String        @unique
  name         String
  cpuCores     Int
  ramMB        Int
  diskGB       Int
  bandwidthTB  Float         @default(1)
  priceCents   Int
  /// LOW introductory MONTHLY price (cents) charged for the FIRST term only; the
  /// plan then RENEWS at the regular `priceCents` (classic hosting promo — e.g.
  /// "$3.99/mo first term, renews at $6.49/mo"). NULL = no intro (the plan bills
  /// `priceCents` from day one). Reused through the existing first-term-discount
  /// plumbing: the order stamps the implied first-term rate on
  /// `Server.termPromoPercent`, and every renewal path (lib/renewal-charge.ts)
  /// reads `priceCents` and knows nothing about this column, so renewal === regular
  /// by construction. Only honoured when strictly below `priceCents`.
  introPriceCents Int?
  /// How many of the first term's months are billed at `introPriceCents` before the
  /// remainder of that term reverts to the regular rate. NULL = the WHOLE first term
  /// is at the intro price (the common "$X first month, then $Y/mo" case is
  /// `introTermMonths = 1`). Ignored when `introPriceCents` is null.
  introTermMonths Int?
  storageTier  String        @default("nvme") // "nvme" | "hdd"
  active       Boolean       @default(true)
  sortOrder    Int           @default(0)
  createdAt    DateTime      @default(now())
  servers      Server[]
  gamePlans    GamePlan[]
  // NxCloud tiers that clone/size their VM from this Plan. A backing Plan for an
  // NxCloud tier is kept `active = false` so it never shows in the VPS wizard.
  nxcloudPlans NxCloudPlan[]
}

