export function DeployCard() {
  const [typed, setTyped] = useState("");
  const [shown, setShown] = useState(0);
  const [phase, setPhase] = useState<"type" | "run" | "done">("type");
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    if (reduce) { setTyped(CMD); setShown(STEPS.length); setPhase("done"); return; }
    let dead = false;
    const push = (fn: () => void, ms: number) => { if (!dead) timers.current.push(setTimeout(fn, ms)); };
    const run = () => {
      setTyped(""); setShown(0); setPhase("type");
      CMD.split("").forEach((_, i) => push(() => setTyped(CMD.slice(0, i + 1)), 55 * i + 300));
      const afterType = 55 * CMD.length + 600;
      push(() => setPhase("run"), afterType);
      STEPS.forEach((_, i) => push(() => setShown(i + 1), afterType + 520 * (i + 1)));
      push(() => setPhase("done"), afterType + 520 * (STEPS.length + 1));
      push(run, afterType + 520 * (STEPS.length + 1) + 3200); // loop
    };
    run();
    return () => { dead = true; timers.current.forEach(clearTimeout); timers.current = []; };
  }, []);

  return (
    <div className="glass overflow-hidden rounded-2xl border-white/10 shadow-2xl glow-brand">
