"use client";

/**
 * Singapore-origin route map — small glowing city markers connected to Singapore
 * by animated arcs that travel outward, like flight paths on a route map. Pure
 * SVG + CSS `offset-path` pulses (same technique as NetworkMap.tsx). Deterministic,
 * SSR-safe, no external assets. Reduced-motion users see the static arcs/dots with
 * no travelling pulse.
 */
const W = 480;
const H = 420;

// Rough relative APAC geography inside the viewBox — not a literal projection,
// just plausible bearings from Singapore (center-west) to each labelled city.
const SGP = { x: 150, y: 210 };
const NODES = [
  { name: "Japan", x: 372, y: 88 },
  { name: "Japan", x: 340, y: 130 },
  { name: "Vietnam", x: 246, y: 140 },
  { name: "Indonesia", x: 210, y: 300 },
  { name: "Australia", x: 372, y: 344 },
];

const arcPath = (a: { x: number; y: number }, b: { x: number; y: number }) => {
  const mx = (a.x + b.x) / 2;
  const my = (a.y + b.y) / 2 - Math.hypot(a.x - b.x, a.y - b.y) * 0.22;
  return `M${a.x},${a.y} Q${mx},${my} ${b.x},${b.y}`;
};

export function SingaporeMap() {
  return (
    <div className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-950/70">
      <style>{`
        @keyframes sgm-pulse { 0% { offset-distance: 0%; opacity: 0; } 10% { opacity: 1; } 85% { opacity: 1; } 100% { offset-distance: 100%; opacity: 0; } }
        @keyframes sgm-blip { 0%, 100% { opacity: .55; transform: scale(1); } 50% { opacity: 1; transform: scale(1.15); } }
        @keyframes sgm-origin { 0%, 100% { opacity: .7; } 50% { opacity: 1; } }
        @media (prefers-reduced-motion: reduce) {
          .sgm-pulse { animation: none !important; opacity: 0; }
          .sgm-blip, .sgm-origin { animation: none !important; opacity: 0.9; }
        }
      `}</style>
      <div aria-hidden className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_30%_50%,rgba(111,71,245,0.14),transparent_65%)]" />
      <svg
        viewBox={`0 0 ${W} ${H}`}
        className="relative block w-full"
        role="img"
        aria-label="Route map showing low-latency connections from Nxeon's Singapore datacenter to Japan, Vietnam, Indonesia and Australia"
      >
        <defs>
          <linearGradient id="sgm-arc" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="#6f47f5" />
            <stop offset="100%" stopColor="#22d3ee" />
          </linearGradient>
          <radialGradient id="sgm-node" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#22d3ee" />
            <stop offset="100%" stopColor="#3b82f6" />
          </radialGradient>
          <radialGradient id="sgm-origin" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#a89aff" />
            <stop offset="100%" stopColor="#6f47f5" />
          </radialGradient>
        </defs>

        {/* faint dot texture for a map-like backdrop */}
        {Array.from({ length: 12 }).map((_, row) =>
          Array.from({ length: 14 }).map((_, col) => (
            <circle
              key={`${row}-${col}`}
              cx={16 + col * 34}
              cy={16 + row * 34}
              r={1}
              fill="rgba(148,163,184,0.10)"
            />
          )),
        )}

        {/* arcs + travelling pulses, Singapore -> each city */}
        {NODES.map((n, i) => {
          const d = arcPath(SGP, n);
          return (
            <g key={`${n.name}-${i}`}>
              <path d={d} fill="none" stroke="url(#sgm-arc)" strokeWidth="1.3" opacity="0.45" />
              <circle
                className="sgm-pulse"
                r="3"
                fill="#22d3ee"
                style={{ offsetPath: `path('${d}')`, animation: `sgm-pulse ${2.8 + i * 0.35}s ${i * 0.4}s linear infinite` }}
              />
            </g>
          );
        })}

        {/* destination nodes */}
        {NODES.map((n, i) => (
          <g key={`node-${n.name}-${i}`}>
            <circle cx={n.x} cy={n.y} r="10" fill="rgba(34,211,238,0.10)" />
            <circle
              className="sgm-blip"
              cx={n.x}
              cy={n.y}
              r="3.2"
              fill="url(#sgm-node)"
              style={{ animation: `sgm-blip ${2 + (i % 3) * 0.4}s ease-in-out infinite` }}
            />
            <g transform={`translate(${n.x + 10}, ${n.y - 8})`}>
              <rect x="0" y="0" width={n.name.length * 6.4 + 12} height="16" rx="8" fill="rgba(10,16,31,0.88)" stroke="rgba(255,255,255,0.08)" />
              <text x="6" y="11.5" fontFamily="ui-monospace, monospace" fontSize="9" fill="#cbd5e1">
                {n.name}
              </text>
            </g>
          </g>
        ))}

        {/* Singapore origin — larger, glowing */}
        <circle cx={SGP.x} cy={SGP.y} r="18" fill="rgba(111,71,245,0.18)" />
        <circle
          className="sgm-origin"
          cx={SGP.x}
          cy={SGP.y}
          r="5.5"
          fill="url(#sgm-origin)"
          style={{ animation: "sgm-origin 2.4s ease-in-out infinite" }}
        />
        <g transform={`translate(${SGP.x - 34}, ${SGP.y + 16})`}>
          <rect x="0" y="0" width="68" height="18" rx="9" fill="rgba(111,71,245,0.16)" stroke="rgba(168,154,255,0.35)" />
          <text x="34" y="12.5" textAnchor="middle" fontFamily="ui-monospace, monospace" fontSize="9.5" fontWeight={600} fill="#e4e0ff">
            Singapore
          </text>
        </g>
      </svg>
    </div>
  );
}

