const BULLETS = ["Full root access", "NVMe + ZFS storage", "Dedicated IPv4", "DDoS protection"];

/** Representative live spec shown in the deploy card (Standard plan — 2 vCPU / 4 GB / 50 GB NVMe / 2 TB). */
const SPECS: { label: string; value: string; target?: number; suffix?: string }[] = [
  { label: "vCPU", value: "2 cores", target: 2, suffix: " cores" },
  { label: "Memory", value: "4 GB", target: 4, suffix: " GB" },
  { label: "Storage", value: "50 GB NVMe", target: 50, suffix: " GB NVMe" },
  { label: "Bandwidth", value: "2 TB", target: 2, suffix: " TB" },
  { label: "IPv4", value: "Dedicated" },
  { label: "Uptime", value: "99.9%" },
];

function useCountUp(target: number | undefined, run: boolean) {
  const [n, setN] = useState(target ?? 0);
  useEffect(() => {
    if (!run || target == null) return;
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    if (reduce) {
      setN(target);
      return;
    }
    let raf = 0;
    const start = performance.now();
    const dur = 900;
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / dur);
      const eased = 1 - Math.pow(1 - t, 3);
      setN(Math.round(target * eased * 10) / 10);
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, run]);
  return n;
}

function SpecRow({ spec, run }: { spec: (typeof SPECS)[number]; run: boolean }) {
  const n = useCountUp(spec.target, run);
  const display = spec.target != null ? `${n}${spec.suffix}` : spec.value;
  return (
    <div className="flex items-center justify-between border-b border-white/[0.06] py-2.5 text-sm last:border-b-0">
      <span className="text-slate-400">{spec.label}</span>
      <span className="font-semibold text-white">{display}</span>
    </div>
  );
}

export function SingaporeHero() {
  const cardRef = useRef<HTMLDivElement | null>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = cardRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            setInView(true);
            io.disconnect();
          }
        }
      },
      { threshold: 0.3 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <section className="relative overflow-hidden">
      <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
      <div className="rail py-20 sm:py-28">
        <div className="grid items-center gap-12 lg:grid-cols-2">
