          <Reveal>
            <span className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-navy-900/80 px-3 py-1.5 text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-300">
              <span className="relative flex h-2 w-2">
