              <span className="grad-text">Hosting</span>
            </h1>

            <p className="mt-6 max-w-xl text-lg leading-relaxed text-slate-400 sm:text-xl">
              NVMe VPS hosting from a Singapore datacenter, built for low latency across Asia-Pacific.
              Full root access, DDoS protection, and instant deploy on every plan.
            </p>

            <div className="mt-9 flex flex-wrap gap-3">
              <Link href="/register" className="btn-deploy px-5 py-3 text-base">
                Deploy now
                <span className="dep-arrow" aria-hidden>
                  <IconBolt size={16} />
                </span>
              </Link>
              <Link href="#pricing" className="btn-secondary px-5 py-3 text-base">
                See pricing
              </Link>
            </div>

            <div className="mt-8 flex flex-wrap items-center gap-x-3 gap-y-2 text-sm text-slate-400">
              {BULLETS.map((b, i) => (
                <span key={b} className="flex items-center gap-3">
                  {i > 0 && <span className="text-slate-600" aria-hidden>·</span>}
                  {b}
                </span>
              ))}
            </div>
          </Reveal>

          {/* Right column: spec/deploy card + route map */}
          <Reveal className="lg:pl-6" delay={80}>
            <div ref={cardRef} className="space-y-4">
              <div className="glass overflow-hidden rounded-2xl border-white/10 shadow-2xl glow-brand">
                <div className="flex items-center gap-2 border-b border-white/[0.06] px-4 py-3 font-mono text-[11px]">
                  <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" />
                  <span className="text-slate-300">sgp1</span>
                  <span className="text-slate-600">·</span>
                  <span className="text-slate-400">Singapore</span>
                  <span className="ml-auto rounded-full border border-emerald-400/30 bg-emerald-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-emerald-300">
                    Live
                  </span>
                </div>

                <div className="px-4 py-3">
                  {SPECS.map((s) => (
                    <SpecRow key={s.label} spec={s} run={inView} />
                  ))}
                </div>

                <div className="border-t border-white/[0.06] bg-white/[0.02] px-4 py-4">
                  <div className="flex items-center justify-between text-xs">
                    <span className="font-medium text-slate-300">Deploying your server</span>
