import { chromium } from "playwright";

const URL = "http://localhost:3941/singapore-vps-hosting";
const outDir = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad";

async function shoot(width, label) {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width, height: 1000 } });
  await page.goto(URL, { waitUntil: "networkidle", timeout: 60000 });

  // scroll through gradually so IntersectionObserver reveals fire
  const total = await page.evaluate(() => document.body.scrollHeight);
  for (let y = 0; y < total; y += 400) {
    await page.evaluate((yy) => window.scrollTo(0, yy), y);
    await page.waitForTimeout(150);
  }
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(500);

  await page.screenshot({ path: `${outDir}/sgvps-${label}-full.png`, fullPage: true });
  await browser.close();
  console.log(`done ${label}`);
}

await shoot(1440, "desktop");
await shoot(390, "mobile");

